-- Adhunik ERP — Phase 8B Supplier Master, Purchase Orders and Material Receipts
begin;
alter table public.numbering_configurations drop constraint if exists numbering_configurations_entity_type_check;
alter table public.numbering_configurations add constraint numbering_configurations_entity_type_check check(entity_type in('EMPLOYEE','CUSTOMER','INQUIRY','ORDER','PROFORMA_INVOICE','PACKING_LIST','DISPATCH','PURCHASE_INDENT','PURCHASE_REQUISITION','SUPPLIER','PURCHASE_ORDER','MATERIAL_RECEIPT'));
insert into public.numbering_configurations(entity_type,prefix,padding,separator) values('SUPPLIER','SUP',4,'/'),('PURCHASE_ORDER','PO',4,'/'),('MATERIAL_RECEIPT','MR',4,'/') on conflict(entity_type) do nothing;
insert into public.numbering_counters(entity_type,current_value) values('SUPPLIER',0),('PURCHASE_ORDER',0),('MATERIAL_RECEIPT',0) on conflict do nothing;

create table public.procurement_year_counters(entity_type text not null check(entity_type in('PURCHASE_ORDER','MATERIAL_RECEIPT')),calendar_year integer not null check(calendar_year between 2000 and 9999),current_value bigint not null default 0 check(current_value>=0),updated_at timestamptz not null default now(),primary key(entity_type,calendar_year));
create or replace function public.allocate_procurement_number(p_type text)returns text language plpgsql security definer set search_path=''as $$declare y integer:=extract(year from current_date)::integer;n bigint;p text;begin if p_type not in('PURCHASE_ORDER','MATERIAL_RECEIPT')then raise exception 'Invalid procurement number type';end if;p:=case when p_type='PURCHASE_ORDER'then'PO'else'MR'end;insert into public.procurement_year_counters values(p_type,y,1,now())on conflict(entity_type,calendar_year)do update set current_value=public.procurement_year_counters.current_value+1,updated_at=now()returning current_value into n;return p||'/'||y||'/'||lpad(n::text,4,'0');end$$;
revoke all on function public.allocate_procurement_number(text)from public,anon,authenticated;

create table public.suppliers(id uuid primary key default gen_random_uuid(),supplier_code text not null unique,supplier_name text not null,trade_name text,gstin text,pan text,contact_person text,phone text,alternate_phone text,email text,website text,address_line_1 text,address_line_2 text,city text,state text,pin_code text,country text not null default'India',payment_terms text,credit_days integer check(credit_days is null or credit_days>=0),notes text,is_active boolean not null default true,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.supplier_activities(id uuid primary key default gen_random_uuid(),supplier_id uuid not null references public.suppliers(id)on delete cascade,activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());
create or replace function public.assign_supplier_code()returns trigger language plpgsql security definer set search_path=''as $$begin if nullif(trim(new.supplier_code),'')is null then new.supplier_code:=public.allocate_business_number('SUPPLIER');end if;return new;end$$;
create trigger assign_supplier_code before insert on public.suppliers for each row execute function public.assign_supplier_code();create trigger set_suppliers_updated_at before update on public.suppliers for each row execute function public.set_updated_at();

alter table public.purchase_requisitions add column supplier_id uuid references public.suppliers(id)on delete restrict;
create table public.purchase_orders(id uuid primary key default gen_random_uuid(),po_number text not null unique,po_date date not null default current_date,requisition_id uuid not null unique references public.purchase_requisitions(id),indent_id uuid not null references public.purchase_indents(id),supplier_id uuid not null references public.suppliers(id),supplier_code_snapshot text not null,supplier_name_snapshot text not null,supplier_gstin_snapshot text,supplier_address_snapshot text,supplier_contact_snapshot text,supplier_phone_snapshot text,supplier_email_snapshot text,billing_address_snapshot text not null,delivery_address_snapshot text not null,payment_terms text,delivery_terms text,expected_delivery_date date,remarks text,terms_conditions text,gst_rate numeric(7,4)not null default 0 check(gst_rate>=0),subtotal numeric(18,2)not null default 0 check(subtotal>=0),gst_amount numeric(18,2)not null default 0 check(gst_amount>=0),freight_amount numeric(18,2)not null default 0 check(freight_amount>=0),grand_total numeric(18,2)not null default 0 check(grand_total>=0),status text not null default'DRAFT'check(status in('DRAFT','CONFIRMED','PARTIALLY_RECEIVED','FULLY_RECEIVED','CANCELLED','CLOSED')),confirmed_at timestamptz,confirmed_by uuid references auth.users(id),cancelled_at timestamptz,cancelled_by uuid references auth.users(id),cancellation_reason text,closed_at timestamptz,created_at timestamptz not null default now(),created_by uuid not null references auth.users(id),updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table public.purchase_order_items(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.purchase_orders(id)on delete cascade,requisition_item_id uuid not null references public.purchase_requisition_items(id),line_number integer not null,item_id uuid references public.items(id),item_code_snapshot text,item_name_snapshot text not null,description_snapshot text,hsn_code_snapshot text,unit_snapshot text not null,pon_quantity numeric(18,3)not null check(pon_quantity>0),quantity numeric(18,3)not null check(quantity>0 and quantity<=pon_quantity),unit_rate numeric(18,4)not null default 0 check(unit_rate>=0),line_amount numeric(18,2)not null default 0 check(line_amount>=0),expected_delivery_date date,remarks text,created_at timestamptz not null default now(),unique(purchase_order_id,line_number));
create table public.purchase_order_activities(id uuid primary key default gen_random_uuid(),purchase_order_id uuid not null references public.purchase_orders(id)on delete cascade,activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());

create table public.material_receipts(id uuid primary key default gen_random_uuid(),receipt_number text not null unique,receipt_date date not null default current_date,purchase_order_id uuid not null references public.purchase_orders(id),supplier_id uuid not null references public.suppliers(id),supplier_name_snapshot text not null,supplier_challan_number text,supplier_invoice_number text,received_at text,received_by uuid not null references auth.users(id),remarks text,status text not null default'CONFIRMED'check(status in('CONFIRMED','CANCELLED')),confirmed_at timestamptz not null default now(),confirmed_by uuid not null references auth.users(id),cancelled_at timestamptz,cancelled_by uuid references auth.users(id),cancellation_reason text,created_at timestamptz not null default now());
create table public.material_receipt_items(id uuid primary key default gen_random_uuid(),material_receipt_id uuid not null references public.material_receipts(id)on delete cascade,purchase_order_item_id uuid not null references public.purchase_order_items(id),line_number integer not null,item_id uuid references public.items(id),item_code_snapshot text,item_name_snapshot text not null,unit_snapshot text not null,ordered_quantity numeric(18,3)not null,previously_received_quantity numeric(18,3)not null default 0,received_quantity numeric(18,3)not null check(received_quantity>0),accepted_quantity numeric(18,3)not null check(accepted_quantity>=0),rejected_quantity numeric(18,3)not null check(rejected_quantity>=0),pending_quantity numeric(18,3)not null check(pending_quantity>=0),remarks text,created_at timestamptz not null default now(),check(accepted_quantity+rejected_quantity=received_quantity),unique(material_receipt_id,purchase_order_item_id));
create table public.material_receipt_activities(id uuid primary key default gen_random_uuid(),material_receipt_id uuid not null references public.material_receipts(id)on delete cascade,activity_type text not null,description text not null,created_by uuid not null references auth.users(id),created_at timestamptz not null default now());

create index suppliers_search on public.suppliers(lower(supplier_name));create index suppliers_state_status on public.suppliers(state,is_active);create index purchase_orders_register on public.purchase_orders(status,po_date desc);create index purchase_orders_supplier on public.purchase_orders(supplier_id);create index purchase_order_items_item on public.purchase_order_items(item_id);create index material_receipts_register on public.material_receipts(status,receipt_date desc);create index material_receipts_po on public.material_receipts(purchase_order_id);create index material_receipt_items_po_item on public.material_receipt_items(purchase_order_item_id);

create or replace function public.save_supplier(p_id uuid,p_data jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare v uuid:=p_id;n text:=nullif(trim(p_data->>'supplier_name'),'');begin if not public.is_erp_manager()then raise exception'Only Admin or Manager can manage suppliers';end if;if n is null then raise exception'Supplier Name is required';end if;if v is null then insert into public.suppliers(supplier_code,supplier_name,trade_name,gstin,pan,contact_person,phone,alternate_phone,email,website,address_line_1,address_line_2,city,state,pin_code,country,payment_terms,credit_days,notes,created_by,updated_by)values(null,n,nullif(trim(p_data->>'trade_name'),''),nullif(trim(p_data->>'gstin'),''),nullif(trim(p_data->>'pan'),''),nullif(trim(p_data->>'contact_person'),''),nullif(trim(p_data->>'phone'),''),nullif(trim(p_data->>'alternate_phone'),''),nullif(trim(p_data->>'email'),''),nullif(trim(p_data->>'website'),''),nullif(trim(p_data->>'address_line_1'),''),nullif(trim(p_data->>'address_line_2'),''),nullif(trim(p_data->>'city'),''),nullif(trim(p_data->>'state'),''),nullif(trim(p_data->>'pin_code'),''),coalesce(nullif(trim(p_data->>'country'),''),'India'),nullif(trim(p_data->>'payment_terms'),''),nullif(p_data->>'credit_days','')::integer,nullif(trim(p_data->>'notes'),''),auth.uid(),auth.uid())returning id into v;insert into public.supplier_activities(supplier_id,activity_type,description,created_by)values(v,'CREATED','Supplier created',auth.uid());else update public.suppliers set supplier_name=n,trade_name=nullif(trim(p_data->>'trade_name'),''),gstin=nullif(trim(p_data->>'gstin'),''),pan=nullif(trim(p_data->>'pan'),''),contact_person=nullif(trim(p_data->>'contact_person'),''),phone=nullif(trim(p_data->>'phone'),''),alternate_phone=nullif(trim(p_data->>'alternate_phone'),''),email=nullif(trim(p_data->>'email'),''),website=nullif(trim(p_data->>'website'),''),address_line_1=nullif(trim(p_data->>'address_line_1'),''),address_line_2=nullif(trim(p_data->>'address_line_2'),''),city=nullif(trim(p_data->>'city'),''),state=nullif(trim(p_data->>'state'),''),pin_code=nullif(trim(p_data->>'pin_code'),''),country=coalesce(nullif(trim(p_data->>'country'),''),'India'),payment_terms=nullif(trim(p_data->>'payment_terms'),''),credit_days=nullif(p_data->>'credit_days','')::integer,notes=nullif(trim(p_data->>'notes'),''),updated_by=auth.uid()where id=v;if not found then raise exception'Supplier not found';end if;insert into public.supplier_activities(supplier_id,activity_type,description,created_by)values(v,'UPDATED','Supplier updated',auth.uid());end if;return v;end$$;
create or replace function public.toggle_supplier(p_id uuid,p_active boolean)returns void language plpgsql security definer set search_path=''as $$begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;update public.suppliers set is_active=p_active,updated_by=auth.uid()where id=p_id;if not found then raise exception'Supplier not found';end if;insert into public.supplier_activities(supplier_id,activity_type,description,created_by)values(p_id,case when p_active then'REACTIVATED'else'DEACTIVATED'end,case when p_active then'Supplier reactivated'else'Supplier deactivated'end,auth.uid());end$$;
create or replace function public.select_pon_supplier(p_requisition_id uuid,p_supplier_id uuid)returns void language plpgsql security definer set search_path=''as $$begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;perform 1 from public.purchase_requisitions where id=p_requisition_id and status='CONFIRMED'for update;if not found then raise exception'Only a confirmed PON can select a supplier';end if;perform 1 from public.suppliers where id=p_supplier_id and is_active;if not found then raise exception'Select an active supplier';end if;if exists(select 1 from public.purchase_orders where requisition_id=p_requisition_id)then raise exception'Supplier cannot change after PO creation';end if;update public.purchase_requisitions set supplier_id=p_supplier_id,updated_at=now(),updated_by=auth.uid()where id=p_requisition_id;insert into public.purchase_requisition_activities values(default,p_requisition_id,'SUPPLIER_SELECTED','Supplier selected for procurement',auth.uid(),default);end$$;

create or replace function public.recalculate_purchase_order(p_id uuid)returns void language plpgsql security definer set search_path=''as $$declare s numeric;g numeric;f numeric;begin update public.purchase_order_items set line_amount=round(quantity*unit_rate,2)where purchase_order_id=p_id;select coalesce(sum(line_amount),0)into s from public.purchase_order_items where purchase_order_id=p_id;select gst_rate,freight_amount into g,f from public.purchase_orders where id=p_id;update public.purchase_orders set subtotal=s,gst_amount=round(s*g/100,2),grand_total=round(s+round(s*g/100,2)+f,2),updated_at=now(),updated_by=auth.uid()where id=p_id;end$$;
revoke all on function public.recalculate_purchase_order(uuid)from public,anon,authenticated;
create or replace function public.create_purchase_order(p_requisition_id uuid)returns uuid language plpgsql security definer set search_path=''as $$declare r public.purchase_requisitions%rowtype;s public.suppliers%rowtype;v uuid;n text;a text;begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;select * into r from public.purchase_requisitions where id=p_requisition_id for update;if not found or r.status<>'CONFIRMED'then raise exception'Confirmed PON required';end if;select id into v from public.purchase_orders where requisition_id=r.id;if v is not null then return v;end if;if r.supplier_id is null then raise exception'Select Supplier first';end if;select * into s from public.suppliers where id=r.supplier_id and is_active;if not found then raise exception'Active Supplier required';end if;select coalesce(registered_office_address,'Address not configured')into a from public.pi_document_settings where id=true;n:=public.allocate_procurement_number('PURCHASE_ORDER');insert into public.purchase_orders(po_number,requisition_id,indent_id,supplier_id,supplier_code_snapshot,supplier_name_snapshot,supplier_gstin_snapshot,supplier_address_snapshot,supplier_contact_snapshot,supplier_phone_snapshot,supplier_email_snapshot,billing_address_snapshot,delivery_address_snapshot,payment_terms,expected_delivery_date,remarks,gst_rate,freight_amount,created_by,updated_by)values(n,r.id,r.indent_id,s.id,s.supplier_code,s.supplier_name,s.gstin,concat_ws(', ',s.address_line_1,s.address_line_2,s.city,s.state,s.pin_code,s.country),s.contact_person,s.phone,s.email,coalesce(a,'Address not configured'),coalesce(a,'Address not configured'),s.payment_terms,r.required_date,r.remarks,r.gst_rate,r.freight_amount,auth.uid(),auth.uid())returning id into v;insert into public.purchase_order_items(purchase_order_id,requisition_item_id,line_number,item_id,item_code_snapshot,item_name_snapshot,description_snapshot,hsn_code_snapshot,unit_snapshot,pon_quantity,quantity,unit_rate,line_amount,expected_delivery_date,remarks)select v,i.id,i.line_number,i.item_id,i.item_code_snapshot,i.item_name_snapshot,i.description_snapshot,i.hsn_code_snapshot,i.unit_snapshot,i.quantity,i.quantity,i.unit_rate,i.line_amount,i.required_date,i.remarks from public.purchase_requisition_items i where i.requisition_id=r.id;perform public.recalculate_purchase_order(v);insert into public.purchase_order_activities values(default,v,'CREATED','Purchase Order created from '||r.requisition_number,auth.uid(),default);insert into public.purchase_requisition_activities values(default,r.id,'PO_CREATED','Purchase Order '||n||' created',auth.uid(),default);return v;end$$;
create or replace function public.save_purchase_order(p_id uuid,p_header jsonb,p_items jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare x jsonb;i integer:=0;q numeric;rate numeric;cap numeric;g numeric:=coalesce(nullif(p_header->>'gst_rate','')::numeric,0);f numeric:=coalesce(nullif(p_header->>'freight_amount','')::numeric,0);begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;perform 1 from public.purchase_orders where id=p_id and status='DRAFT'for update;if not found then raise exception'Draft PO not found';end if;if g<0 or f<0 then raise exception'GST and Freight must not be negative';end if;if jsonb_array_length(p_items)=0 then raise exception'At least one item is required';end if;update public.purchase_orders set po_date=coalesce(nullif(p_header->>'po_date','')::date,po_date),billing_address_snapshot=trim(p_header->>'billing_address'),delivery_address_snapshot=trim(p_header->>'delivery_address'),payment_terms=nullif(trim(p_header->>'payment_terms'),''),delivery_terms=nullif(trim(p_header->>'delivery_terms'),''),expected_delivery_date=nullif(p_header->>'expected_delivery_date','')::date,remarks=nullif(trim(p_header->>'remarks'),''),terms_conditions=nullif(trim(p_header->>'terms_conditions'),''),gst_rate=g,freight_amount=f,updated_by=auth.uid()where id=p_id;for x in select value from jsonb_array_elements(p_items)loop i:=i+1;q:=(x->>'quantity')::numeric;rate:=coalesce(nullif(x->>'unit_rate','')::numeric,0);select pon_quantity into cap from public.purchase_order_items where id=(x->>'id')::uuid and purchase_order_id=p_id;if not found or q<=0 or q>cap or rate<0 then raise exception'Invalid quantity/rate on line %',i;end if;update public.purchase_order_items set quantity=q,unit_rate=rate,description_snapshot=nullif(trim(x->>'description'),''),expected_delivery_date=nullif(x->>'expected_delivery_date','')::date,remarks=nullif(trim(x->>'remarks'),'')where id=(x->>'id')::uuid;end loop;perform public.recalculate_purchase_order(p_id);insert into public.purchase_order_activities values(default,p_id,'UPDATED','Draft Purchase Order updated',auth.uid(),default);return p_id;end$$;
create or replace function public.confirm_purchase_order(p_id uuid)returns void language plpgsql security definer set search_path=''as $$begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;perform 1 from public.purchase_orders where id=p_id and status='DRAFT'and supplier_id is not null and nullif(trim(billing_address_snapshot),'')is not null and nullif(trim(delivery_address_snapshot),'')is not null for update;if not found then raise exception'Valid Draft PO not found';end if;if exists(select 1 from public.purchase_order_items where purchase_order_id=p_id and(quantity<=0 or quantity>pon_quantity or unit_rate<0))or not exists(select 1 from public.purchase_order_items where purchase_order_id=p_id)then raise exception'Invalid PO items';end if;perform public.recalculate_purchase_order(p_id);update public.purchase_orders set status='CONFIRMED',confirmed_at=now(),confirmed_by=auth.uid(),updated_by=auth.uid()where id=p_id;insert into public.purchase_order_activities values(default,p_id,'CONFIRMED','Purchase Order confirmed',auth.uid(),default);end$$;
create or replace function public.close_purchase_order(p_id uuid)returns void language plpgsql security definer set search_path=''as $$begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;update public.purchase_orders set status='CLOSED',closed_at=now(),updated_at=now(),updated_by=auth.uid()where id=p_id and status='FULLY_RECEIVED';if not found then raise exception'Only a fully received PO can be closed';end if;insert into public.purchase_order_activities values(default,p_id,'CLOSED','Fully received Purchase Order closed',auth.uid(),default);end$$;
create or replace function public.cancel_purchase_order(p_id uuid,p_reason text)returns void language plpgsql security definer set search_path=''as $$begin if not public.is_erp_manager()or nullif(trim(p_reason),'')is null then raise exception'Authorization and reason required';end if;if exists(select 1 from public.material_receipts where purchase_order_id=p_id and status='CONFIRMED')then raise exception'PO with confirmed receipts cannot be cancelled';end if;update public.purchase_orders set status='CANCELLED',cancelled_at=now(),cancelled_by=auth.uid(),cancellation_reason=trim(p_reason),updated_by=auth.uid()where id=p_id and status in('DRAFT','CONFIRMED');if not found then raise exception'PO cannot be cancelled';end if;insert into public.purchase_order_activities values(default,p_id,'CANCELLED','Purchase Order cancelled: '||trim(p_reason),auth.uid(),default);end$$;

create or replace function public.refresh_purchase_order_receipt_status(p_id uuid)returns void language plpgsql security definer set search_path=''as $$declare any_received boolean;all_received boolean;begin select coalesce(bool_or(received>0),false),coalesce(bool_and(received>=quantity),false)into any_received,all_received from(select oi.quantity,coalesce(sum(ri.received_quantity)filter(where r.status='CONFIRMED'),0)received from public.purchase_order_items oi left join public.material_receipt_items ri on ri.purchase_order_item_id=oi.id left join public.material_receipts r on r.id=ri.material_receipt_id where oi.purchase_order_id=p_id group by oi.id)q;update public.purchase_orders set status=case when all_received then'FULLY_RECEIVED'when any_received then'PARTIALLY_RECEIVED'else'CONFIRMED'end,updated_at=now(),updated_by=auth.uid()where id=p_id and status not in('CANCELLED','CLOSED');end$$;
revoke all on function public.refresh_purchase_order_receipt_status(uuid)from public,anon,authenticated;
create or replace function public.record_material_receipt(p_po_id uuid,p_header jsonb,p_items jsonb)returns uuid language plpgsql security definer set search_path=''as $$declare po public.purchase_orders%rowtype;v uuid;n text;x jsonb;oi public.purchase_order_items%rowtype;prev numeric;recv numeric;acc numeric;rej numeric;i integer:=0;begin if not public.is_erp_manager()then raise exception'Unauthorized';end if;select * into po from public.purchase_orders where id=p_po_id and status in('CONFIRMED','PARTIALLY_RECEIVED')for update;if not found then raise exception'Open confirmed PO required';end if;n:=public.allocate_procurement_number('MATERIAL_RECEIPT');insert into public.material_receipts(receipt_number,receipt_date,purchase_order_id,supplier_id,supplier_name_snapshot,supplier_challan_number,supplier_invoice_number,received_at,received_by,remarks,confirmed_by)values(n,coalesce(nullif(p_header->>'receipt_date','')::date,current_date),po.id,po.supplier_id,po.supplier_name_snapshot,nullif(trim(p_header->>'challan'),''),nullif(trim(p_header->>'invoice'),''),nullif(trim(p_header->>'received_at'),''),auth.uid(),nullif(trim(p_header->>'remarks'),''),auth.uid())returning id into v;for x in select value from jsonb_array_elements(p_items)loop recv:=coalesce(nullif(x->>'received_quantity','')::numeric,0);if recv>0 then i:=i+1;select * into oi from public.purchase_order_items where id=(x->>'purchase_order_item_id')::uuid and purchase_order_id=po.id;if not found then raise exception'Invalid PO item';end if;select coalesce(sum(ri.received_quantity),0)into prev from public.material_receipt_items ri join public.material_receipts r on r.id=ri.material_receipt_id where ri.purchase_order_item_id=oi.id and r.status='CONFIRMED';acc:=coalesce(nullif(x->>'accepted_quantity','')::numeric,0);rej:=coalesce(nullif(x->>'rejected_quantity','')::numeric,0);if recv<=0 or prev+recv>oi.quantity or acc<0 or rej<0 or acc+rej<>recv then raise exception'Invalid receipt quantity for line %',oi.line_number;end if;insert into public.material_receipt_items(material_receipt_id,purchase_order_item_id,line_number,item_id,item_code_snapshot,item_name_snapshot,unit_snapshot,ordered_quantity,previously_received_quantity,received_quantity,accepted_quantity,rejected_quantity,pending_quantity,remarks)values(v,oi.id,oi.line_number,oi.item_id,oi.item_code_snapshot,oi.item_name_snapshot,oi.unit_snapshot,oi.quantity,prev,recv,acc,rej,oi.quantity-prev-recv,nullif(trim(x->>'remarks'),''));end if;end loop;if i=0 then raise exception'Enter at least one received quantity';end if;insert into public.material_receipt_activities values(default,v,'CONFIRMED','Material Receipt recorded and confirmed; inventory unchanged',auth.uid(),default);insert into public.purchase_order_activities values(default,po.id,'MATERIAL_RECEIPT','Material Receipt '||n||' confirmed; inventory unchanged',auth.uid(),default);perform public.refresh_purchase_order_receipt_status(po.id);return v;end$$;
create or replace function public.cancel_material_receipt(p_id uuid,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare po uuid;begin if not public.is_erp_manager()or nullif(trim(p_reason),'')is null then raise exception'Authorization and reason required';end if;update public.material_receipts set status='CANCELLED',cancelled_at=now(),cancelled_by=auth.uid(),cancellation_reason=trim(p_reason)where id=p_id and status='CONFIRMED'returning purchase_order_id into po;if po is null then raise exception'Receipt cannot be cancelled';end if;insert into public.material_receipt_activities values(default,p_id,'CANCELLED','Material Receipt cancelled: '||trim(p_reason),auth.uid(),default);perform public.refresh_purchase_order_receipt_status(po);end$$;

insert into public.procurement_year_counters(entity_type,calendar_year,current_value)
select case when n like'PO/%'then'PURCHASE_ORDER'else'MATERIAL_RECEIPT'end,substring(n from '/([0-9]{4})/')::integer,max(substring(n from '/([0-9]+)$')::bigint) from(select po_number n from public.purchase_orders where po_number~'^PO/[0-9]{4}/[0-9]+$'union all select receipt_number from public.material_receipts where receipt_number~'^MR/[0-9]{4}/[0-9]+$')z group by 1,2 on conflict(entity_type,calendar_year)do update set current_value=greatest(public.procurement_year_counters.current_value,excluded.current_value),updated_at=now();
alter table public.procurement_year_counters enable row level security;alter table public.suppliers enable row level security;alter table public.supplier_activities enable row level security;alter table public.purchase_orders enable row level security;alter table public.purchase_order_items enable row level security;alter table public.purchase_order_activities enable row level security;alter table public.material_receipts enable row level security;alter table public.material_receipt_items enable row level security;alter table public.material_receipt_activities enable row level security;
create policy "Managers read suppliers"on public.suppliers for select to authenticated using(public.is_erp_manager());create policy "Managers read supplier activity"on public.supplier_activities for select to authenticated using(public.is_erp_manager());create policy "Managers read purchase orders"on public.purchase_orders for select to authenticated using(public.is_erp_manager());create policy "Managers read purchase order items"on public.purchase_order_items for select to authenticated using(public.is_erp_manager());create policy "Managers read purchase order activity"on public.purchase_order_activities for select to authenticated using(public.is_erp_manager());create policy "Managers read material receipts"on public.material_receipts for select to authenticated using(public.is_erp_manager());create policy "Managers read material receipt items"on public.material_receipt_items for select to authenticated using(public.is_erp_manager());create policy "Managers read material receipt activity"on public.material_receipt_activities for select to authenticated using(public.is_erp_manager());
grant select on public.suppliers,public.supplier_activities,public.purchase_orders,public.purchase_order_items,public.purchase_order_activities,public.material_receipts,public.material_receipt_items,public.material_receipt_activities to authenticated;revoke all on public.procurement_year_counters from public,anon,authenticated;revoke insert,update,delete on public.suppliers,public.supplier_activities,public.purchase_orders,public.purchase_order_items,public.purchase_order_activities,public.material_receipts,public.material_receipt_items,public.material_receipt_activities from authenticated;
grant execute on function public.save_supplier(uuid,jsonb),public.toggle_supplier(uuid,boolean),public.select_pon_supplier(uuid,uuid),public.create_purchase_order(uuid),public.save_purchase_order(uuid,jsonb,jsonb),public.confirm_purchase_order(uuid),public.cancel_purchase_order(uuid,text),public.close_purchase_order(uuid),public.record_material_receipt(uuid,jsonb,jsonb),public.cancel_material_receipt(uuid,text)to authenticated;
commit;